-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.is_invited(email text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select public.is_allowed_email(email)
     and (
       coalesce((select s.open_to_domain from public.access_settings s), false)
       or exists (select 1 from public.invited_emails i where i.email = lower(trim(is_invited.email)))
     );
$function$;

grant execute on function public.is_invited(email text) to service_role;
grant execute on function public.is_invited(email text) to supabase_auth_admin;
